@php
    $themeOrganization = (isset($organization) && $organization instanceof \App\Models\Organization) ? $organization : null;
    $safeColor = fn ($color, $fallback) => is_string($color) && preg_match('/^#[0-9a-fA-F]{6}$/', $color) ? $color : $fallback;
    $primary = $safeColor($themeOrganization?->primary_color, '#2459a6');
    $accent = $safeColor($themeOrganization?->accent_color, '#12856f');
    $contrastText = function ($hex) {
        $parts = [hexdec(substr($hex,1,2)), hexdec(substr($hex,3,2)), hexdec(substr($hex,5,2))];
        $linear = array_map(function ($c) { $c=$c/255; return $c <= 0.04045 ? $c/12.92 : (($c+0.055)/1.055)**2.4; }, $parts);
        return (0.2126*$linear[0] + 0.7152*$linear[1] + 0.0722*$linear[2]) > 0.179 ? '#000000' : '#ffffff';
    };
@endphp
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>HR Prototype</title>
<style>:root{--primary:{{ $primary }};--on-primary:{{ $contrastText($primary) }};--accent:{{ $accent }};--on-accent:{{ $contrastText($accent) }}}body{margin:0;background:#f3f6fb;color:#1b2739;font:15px system-ui}header{background:var(--primary);color:var(--on-primary);padding:16px 5%;display:flex;align-items:center;justify-content:space-between;gap:12px}header a{color:var(--on-primary)}header img{max-height:42px;max-width:120px;background:white;border-radius:4px;vertical-align:middle}main{max-width:1050px;margin:30px auto;padding:0 20px}section{background:white;border:1px solid #dce4ee;border-radius:10px;padding:22px;margin:18px 0}h1,h2{margin-top:0}input,select,button{font:inherit;padding:9px;border:1px solid #bbc7d6;border-radius:5px;max-width:100%;box-sizing:border-box}button{background:var(--primary);color:var(--on-primary);border:0;cursor:pointer}a{color:#17477d}label{display:block;margin:10px 0}label input,label select{display:block;margin-top:4px}ul{line-height:1.8}.error{color:#9d1e26}.success{color:#176846}.row{display:flex;gap:12px;flex-wrap:wrap;align-items:end}img.logo{max-height:65px;max-width:180px}small{color:#526477}.theme-accent{background:var(--accent);color:var(--on-accent);padding:6px 10px;border-radius:5px;display:inline-block}</style></head><body><header><div>@if($themeOrganization?->logo_path)<img src="{{ asset('storage/'.$themeOrganization->logo_path) }}" alt=""> @endif<a href="{{ route('home') }}">{{ $themeOrganization?->name ?? 'HR Prototype' }}</a></div>@auth<form method="post" action="{{ route('logout') }}">@csrf <button>Sign out</button></form>@endauth</header><main>@if(session('status'))<p class="success">{{ session('status') }}</p>@endif @if($errors->any())<div class="error"><ul>@foreach($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul></div>@endif @yield('content')</main></body></html>
